import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { separatorClassNameByOrientation } from "./view";
import type { SeparatorOrientation } from "./view";

export type { SeparatorOrientation };

export {
  horizontalSeparatorClassName,
  separatorBaseClassName,
  separatorClassNameByOrientation,
  verticalSeparatorClassName,
} from "./view";

export type ViewConfig = Readonly<{
  /** The visual and accessibility orientation of the separator. */
  orientation?: SeparatorOrientation;
  /** Additional class appended to the default orientation classes. */
  className?: string | undefined;
  /** Inline styles applied to the separator element. */
  style?: SeparatorStyle | undefined;
}>;

/** Inline style object accepted by Foldkit h.Style. */
export type SeparatorStyle = Readonly<Record<string, string>>;

/** Renders an accessible Base UI-style separator. */
export const view = <ParentMessage>({
  orientation = "horizontal",
  className,
  style,
}: ViewConfig = {}): Html => {
  const h = html<ParentMessage>();
  const classNames = [separatorClassNameByOrientation(orientation), className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.div(
    [
      h.Attribute("role", "separator"),
      h.Attribute("aria-orientation", orientation),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames),
    ],
    []
  );
};

export type SeparatorOrientation = "horizontal" | "vertical";

export const separatorBaseClassName = "shrink-0 bg-gray-200";

export const horizontalSeparatorClassName = "h-px w-full";

export const verticalSeparatorClassName = "h-6 w-px";

export const separatorClassNameByOrientation = (
  orientation: SeparatorOrientation = "horizontal"
): string =>
  orientation === "vertical"
    ? `${separatorBaseClassName} ${verticalSeparatorClassName}`
    : `${separatorBaseClassName} ${horizontalSeparatorClassName}`;

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Separator from "./index";

const view = (): Html => {
  const h = html<never>();

  return h.div([], [h.p([], ["Account"]), Separator.view()]);
};

const verticalView = (): Html => {
  const h = html<never>();

  return h.div(
    [],
    [
      h.div(
        [h.Class("flex items-center gap-3")],
        [
          h.span([], ["Preview"]),
          Separator.view({
            orientation: "vertical",
            className: "separator-override",
            style: { blockSize: "2rem" },
          }),
          h.span([], ["Code"]),
        ]
      ),
    ]
  );
};

describe("Separator registry view", () => {
  test("renders Base UI horizontal separator attributes", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Account")).toExist(),
      Scene.expect(Scene.role("separator")).toHaveAttr(
        "aria-orientation",
        "horizontal"
      ),
      Scene.expect(Scene.role("separator")).toHaveAttr(
        "data-orientation",
        "horizontal"
      ),
      Scene.expect(Scene.role("separator")).toHaveClass("bg-gray-200")
    );
  });

  test("renders Base UI vertical separator attributes and style hooks", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view: verticalView,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Preview")).toExist(),
      Scene.expect(Scene.role("separator")).toHaveAttr(
        "aria-orientation",
        "vertical"
      ),
      Scene.expect(Scene.role("separator")).toHaveAttr(
        "data-orientation",
        "vertical"
      ),
      Scene.expect(Scene.role("separator")).toHaveClass("separator-override"),
      Scene.expect(Scene.role("separator")).toHaveStyle("blockSize", "2rem")
    );
  });
});
